// Simulador de evento POS sin datos personales.
return [
  {
    json: {
      ticket_id: 6,
      mesa: "11",
      comensales: 5,
      hora_apertura: "2026-06-19 13:35:00",
      minutos_abierto: 20,
      max: 5,
      items: [
        { categoria: "Pizzas", nombre: "Pizza Burrata", cantidad: 2 },
        { categoria: "Entradas", nombre: "Aros de Calamar", cantidad: 1 },
        { categoria: "Jugos & Smoothies", nombre: "Agua de Coco", cantidad: 5 }
      ],
      excluir: []
    }
  }
];

for (const item of $input.all()) {
  const minutos = Number(item.json.minutos_transcurridos || 0);

  // 1. Extraemos la hora en la que se abrió la cuenta (o la hora actual si no viene el dato)
  const fechaApertura = item.json.hora_apertura ? new Date(item.json.hora_apertura) : new Date();
  const hora = fechaApertura.getHours(); // Devuelve un número del 0 al 23

  // 2. Determinamos el Turno (Desayuno, Comida o Cena)
  let turno = "COMIDA";
  if (hora < 13) {
    turno = "DESAYUNO";
  } else if (hora >= 18) {
    turno = "CENA";
  }

  // 3. Determinamos la Etapa por minutos transcurridos
  let numeroEtapa = 1;
  let nombreEtapa = "ENTRADAS";
  if (minutos >= 15 && minutos <= 45) {
    numeroEtapa = 2;
    nombreEtapa = "DESARROLLO";
  } else if (minutos > 45) {
    numeroEtapa = 3;
    nombreEtapa = "CIERRE";
  }

  // 4. Matriz de Categorías: Qué recomendar según (Turno x Etapa)
  // IDs de Categorías: 1=Desayunos, 2=Entradas, 3=Sopas&Cremas, 4=Pastas, 5=Platos Fuertes, 6=Ensaladas, 7=Pizzas, 8=Para Picar
  const matrizCategorias = {
    DESAYUNO: {
      1: "1,8",     // Inicio (<15 min): Frutas, molletes, pan dulce o para picar
      2: "1",       // Desarrollo (15-45 min): Chilaquiles, huevos, baguettes, enchiladas
      3: "1"        // Cierre (>45 min): Opciones dulces (Pan Francés Estilo C.P.) y café
    },
    COMIDA: {
      1: "2,3,8",   // Inicio: Entradas, sopas, cremas y para picar
      2: "4,5,6,7", // Desarrollo: Platos fuertes, pastas, ensaladas y pizzas
      3: "1"        // Cierre: Café, infusiones o postres
    },
    CENA: {
      1: "2,7,8",   // Inicio: Entradas, para picar o pizzas rápidas para compartir
      2: "4,5,6,7", // Desarrollo: Platos fuertes, pastas, pizzas y ensaladas
      3: "1"        // Cierre: Café o digestivos
    }
  };

  // Asignamos las variables al JSON que viajará al Switch y luego al SQL
  item.json.turno = turno;
  item.json.etapa = numeroEtapa;
  item.json.etapa_nombre = nombreEtapa;
  item.json.categorias_validas = matrizCategorias[turno][numeroEtapa];
}

return $input.all();

// 1. Recibimos el arreglo de productos devueltos por el nodo MySQL (máximo 3 por el LIMIT 3 del SQL)
const candidatos = $input.all().map(item => item.json);

if (!candidatos || candidatos.length === 0) {
  return [{ json: { status: "EMPTY", message: "No hay recomendaciones disponibles para mostrar." } }];
}

// 2. Separamos el ganador (índice 0, el de mayor puntaje) y los dos de respaldo para el botón "& OTRA SUGERENCIA"
const ganadora = candidatos[0];
const respaldos = candidatos.slice(1);

// 3. Fabricamos el argumento de venta para apoyar al mesero en el piso
let argumentoMesero = `Excelente opción de nuestra cocina para acompañar el pedido actual.`;

if (Number(ganadora.veces_cliente) > 0) {
  argumentoMesero = `Favorito del cliente: Lo ha pedido ${ganadora.veces_cliente} veces en visitas anteriores.`;
} else if (Number(ganadora.veces_similares) > 0) {
  argumentoMesero = `Alta tendencia: Muy pedido por mesas similares para maridar o compartir.`;
} else if (ganadora.etiqueta_menu === 'Premium') {
  argumentoMesero = `Corte Choice Angus recomendado por el Chef para centro de mesa.`;
} else if (ganadora.etiqueta_menu) {
  argumentoMesero = `Opción de especialidad (${ganadora.etiqueta_menu}) recomendada en este momento.`;
}

// 4. Retornamos la estructura exacta que espera la pantalla de tu sistema POS
return [
  {
    json: {
      status: "SUCCESS",
      sugerencia_principal: {
        producto_id: ganadora.producto_id,
        nombre: ganadora.producto_nombre,
        precio: Number(ganadora.precio),
        categoria: ganadora.categoria_nombre,
        etiqueta: ganadora.etiqueta_menu || "Sugerencia",
        puntaje_algoritmico: Number(ganadora.puntaje),
        argumento_mesero: argumentoMesero
      },
      opciones_respaldo: respaldos.map(item => ({
        producto_id: item.producto_id,
        nombre: item.producto_nombre,
        precio: Number(item.precio),
        etiqueta: item.etiqueta_menu || ""
      }))
    }
  }
];

